jsimport { ref } from 'vue'
export default {
 setup() {
 const count = ref(0)
 function increment() {
 // .value is needed in JavaScript
 count.value++
 }
 // don't forget to expose the function as well.
 return {
 count,
 increment
 }
 }
}

